WITH eligible AS (SELECT s.* FROM stores s WHERE NOT EXISTS (SELECT 1 FROM store_sales ch WHERE ch.store_id = s.id AND ch.store_id = 6)), with_last AS (SELECT s.id, s.opened_date, latest.store_sale_units FROM eligible s LEFT JOIN LATERAL (SELECT c.units AS store_sale_units FROM store_sales c WHERE c.store_id = s.id ORDER BY c.revenue DESC, c.id DESC LIMIT 1) latest ON TRUE), with_windows AS (SELECT *, RANK() OVER (ORDER BY store_sale_units DESC NULLS FIRST) AS store_sale_units_rank, SUM(store_sale_units) OVER (ORDER BY opened_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_store_sale_units, LAG(store_sale_units, 1) OVER (ORDER BY opened_date ASC, id ASC) AS prev_store_sale_units FROM with_last), kept AS (SELECT s.* FROM with_windows s WHERE NOT EXISTS (SELECT 1 FROM inventory ch WHERE ch.store_id = s.id AND ch.last_restock <= s.opened_date)), with_last_stores AS (SELECT s.id, s.opened_date, s.store_sale_units, top1.sale_date, top1.store_sale_revenue FROM kept s JOIN LATERAL (SELECT c.sale_date, c.revenue AS store_sale_revenue FROM store_sales c WHERE c.store_id = s.id ORDER BY c.units DESC, c.id DESC LIMIT 1) top1 ON TRUE), remaining_keys AS (SELECT id FROM with_last_stores EXCEPT DISTINCT SELECT id FROM stores WHERE region IN ('West', 'East')), verified AS (SELECT s.* FROM with_last_stores s JOIN remaining_keys k ON s.id = k.id) SELECT opened_date, store_sale_units, sale_date, store_sale_revenue FROM verified
